<script setup lang="ts">import {onMounted,ref} from 'vue';import http from '../api/http';import PublicState from './PublicState.vue';const loading=ref(true),error=ref(''),items=ref<any[]>([]),keyword=ref('');async function load(){loading.value=true;try{items.value=(await http.get('/public/doctors',{params:{page:1,pageSize:50,keyword:keyword.value||undefined}})).data.data.records;}catch(e:any){error.value=e.message??'加载失败';}finally{loading.value=false;}}onMounted(load);</script><template><section class="page"><h1>医生团队</h1><form @submit.prevent="load"><input v-model="keyword" placeholder="搜索医生姓名或编号"><button>搜索</button></form><PublicState :loading="loading" :error="error" :empty="!items.length"><router-link v-for="item in items" :key="item.id" :to="`/doctors/${item.id}`" class="detail"><h2>{{item.name}} <small>{{item.title}}</small></h2><p>{{item.departments.map((x:any)=>x.name).join('、')}}</p><p>{{item.specialties.map((x:any)=>x.name).join('、')||item.specialtySummary}}</p></router-link></PublicState></section></template>
